package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckGlobalThis.JSDocInfo;
import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static com.google.javascript.jscomp.CheckGlobalThis.Token;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;
    private NodeTraversal mockTraversal;

    @Before
    public void setUp() {
        checkGlobalThis = new CheckGlobalThis();
        mockTraversal = mock(NodeTraversal.class);
    }

    private Node createNode(int type) {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(type);
        return node;
    }

    @Test
    public void testNonFunctionNodeReturnsTrue() {
        Node n = createNode(Token.VAR);
        Node parent = createNode(Token.BLOCK);
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithConstructorJsDocReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(true);

        // We need to spy or mock the class to override getFunctionJsDocInfo 
        // since it's a private/protected method of the same class.
        CheckGlobalThis spyCheck = Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);

        assertFalse(spyCheck.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithThisTypeJsDocReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(false);
        when(jsDoc.hasThisType()).thenReturn(true);

        CheckGlobalThis spyCheck = Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);

        assertFalse(spyCheck.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithOverrideJsDocReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(false);
        when(jsDoc.hasThisType()).thenReturn(false);
        when(jsDoc.isOverride()).thenReturn(true);

        CheckGlobalThis spyCheck = Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);

        assertFalse(spyCheck.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithNullJsDocAndValidParentReturnsTrue() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);

        CheckGlobalThis spyCheck = Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(null);

        assertTrue(spyCheck.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithInvalidParentReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.EXPRESSION); // Not BLOCK, SCRIPT, NAME, or ASSIGN

        CheckGlobalThis spyCheck = Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(null);

        assertFalse(spyCheck.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithValidParents() {
        int[] validParents = {Token.BLOCK, Token.SCRIPT, Token.NAME, Token.ASSIGN};
        for (int pType : validParents) {
            Node n = createNode(Token.FUNCTION);
            Node parent = createNode(pType);
            CheckGlobalThis spyCheck = Mockito.spy(checkGlobalThis);
            when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(null);
            assertTrue("Failed for parent type: " + pType, spyCheck.shouldTraverse(mockTraversal, n, parent));
        }
    }

    @Test
    public void testAssignmentLeftHandSide() {
        Node lhs = createNode(Token.NAME);
        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // Testing n == lhs
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, lhs, parent));
    }

    @Test
    public void testAssignmentRightHandSideValid() {
        Node lhs = createNode(Token.NAME);
        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, rhs, parent));
    }

    @Test
    public void testAssignmentRightHandSidePrototypeGetPropReturnsFalse() {
        Node lhs = createNode(Token.GETPROP);
        Node lastChild = createNode(Token.NAME);
        when(lastChild.getString()).thenReturn("prototype");
        when(lhs.getLastChild()).thenReturn(lastChild);

        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, rhs, parent));
    }

    @Test
    public void testAssignmentRightHandSideQualifiedNamePrototypeReturnsFalse() {
        Node lhs = createNode(Token.NAME);
        when(lhs.getQualifiedName()).thenReturn("Object.prototype.toString");

        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, rhs, parent));
    }

    @Test
    public void testAssignmentRightHandSideQualifiedNameNullReturnsTrue() {
        Node lhs = createNode(Token.NAME);
        when(lhs.getQualifiedName()).thenReturn(null);

        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, rhs, parent));
    }

    @Test
    public void testNullParent() {
        Node n = createNode(Token.NAME);
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, null));
    }
}
